-- Purpose-specific current-school operations. Auth provisioning and tenant creation stay privileged local setup.
begin;
create table app.school_policy_versions(
 school_id uuid not null references app.schools(id),id uuid not null default gen_random_uuid(),version integer not null check(version>0),parent_attendance_visible boolean not null default false,parent_upcoming_visible boolean not null default false,
 student_messaging_enabled boolean not null default false check(student_messaging_enabled=false),recognition_enabled boolean not null default false,leaderboard_enabled boolean not null default false,analytics_enabled boolean not null default false,
 reason text not null check(length(btrim(reason))between 1 and 1000),approved_by uuid not null,approved_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,version),foreign key(school_id,approved_by)references app.memberships(school_id,actor_id),check(not leaderboard_enabled or recognition_enabled));
create table app.attendance_revisions(
 school_id uuid not null,id uuid not null default gen_random_uuid(),class_id uuid not null,learner_id uuid not null,occurred_on date not null,revision integer not null check(revision>0),status text not null check(status in('present','absent','late','excused')),note text not null check(length(note)<=1000),correction_reason text,recorded_by uuid not null,recorded_at timestamptz not null default clock_timestamp(),previous_id uuid,
 primary key(school_id,id),unique(school_id,class_id,learner_id,occurred_on,revision),foreign key(school_id,class_id)references app.classes(school_id,id),foreign key(school_id,learner_id)references app.memberships(school_id,actor_id),foreign key(school_id,recorded_by)references app.memberships(school_id,actor_id),foreign key(school_id,previous_id)references app.attendance_revisions(school_id,id),check(revision=1 or length(btrim(correction_reason))between 1 and 1000));
create table app.timetable_entries(
 school_id uuid not null,id uuid not null default gen_random_uuid(),class_id uuid not null,subject_id uuid not null,teacher_id uuid not null,day_of_week integer not null check(day_of_week between 0 and 6),starts_at time not null,ends_at time not null,effective_from date not null,effective_to date not null,location text not null check(length(location)<=200),created_by uuid not null,
 primary key(school_id,id),foreign key(school_id,class_id)references app.classes(school_id,id),foreign key(school_id,subject_id)references app.subjects(school_id,id),foreign key(school_id,teacher_id)references app.memberships(school_id,actor_id),foreign key(school_id,created_by)references app.memberships(school_id,actor_id),check(ends_at>starts_at and effective_to>=effective_from));
create table app.calendar_events(
 school_id uuid not null references app.schools(id),id uuid not null default gen_random_uuid(),class_id uuid,title text not null check(length(btrim(title))between 1 and 200),description text not null check(length(description)<=2000),starts_at timestamptz not null,ends_at timestamptz not null,parent_visible boolean not null default false,created_by uuid not null,
 primary key(school_id,id),foreign key(school_id,class_id)references app.classes(school_id,id),foreign key(school_id,created_by)references app.memberships(school_id,actor_id),check(ends_at>starts_at));
create table app.report_periods(
 school_id uuid not null,id uuid not null default gen_random_uuid(),term_id uuid not null,name text not null check(length(btrim(name))between 1 and 200),starts_on date not null,ends_on date not null,parent_visible boolean not null default false,created_by uuid not null,
 primary key(school_id,id),foreign key(school_id,term_id)references app.terms(school_id,id),foreign key(school_id,created_by)references app.memberships(school_id,actor_id),check(ends_on>starts_on));
create index attendance_learner_date_idx on app.attendance_revisions(school_id,learner_id,occurred_on desc,revision desc);
create index timetable_class_idx on app.timetable_entries(school_id,class_id,id);create index calendar_school_time_idx on app.calendar_events(school_id,starts_at,id);
create function "authorization".school_operations_access(target_school uuid)returns boolean language sql stable security definer set search_path=''as $$select coalesce("authorization".can_access_school(target_school)and"authorization".has_entitlement(target_school,'school.operations'),false)$$;
create function internal.require_school_admin()returns void language plpgsql security definer set search_path=''as $$begin if not"authorization".school_operations_access("authorization".school_id())or"authorization".current_role("authorization".school_id())<>'admin'then raise exception 'Current school administrator required'using errcode='42501';end if;end$$;
create function "authorization".can_record_attendance(target_school uuid,target_class uuid,target_student uuid)returns boolean language sql stable security definer set search_path=''as $$select coalesce("authorization".school_operations_access(target_school)and"authorization".current_role(target_school)in('admin','teacher')and"authorization".can_view_class(target_school,target_class)and"authorization".can_view_person(target_school,target_student)and exists(select 1 from app.enrollments e join app.classes c on c.school_id=e.school_id and c.id=e.class_id join app.memberships m on m.school_id=e.school_id and m.actor_id=e.student_actor_id where e.school_id=target_school and e.class_id=target_class and e.student_actor_id=target_student and c.status='active'and m.role='student'and m.status='active'and e.status='active'and e.effective_from<=now()and(e.effective_to is null or e.effective_to>now())),false)$$;
create function internal.validate_school_payload(command_name text,payload jsonb)returns void language plpgsql set search_path=''as $$
declare fields text[];
begin
 fields:=case command_name
 when'details.update'then array['name','countryCode','languages']when'year.create'then array['name','startsOn','endsOn']when'term.create'then array['academicYearId','name','startsOn','endsOn']when'yeargroup.create'then array['name','ordinal']when'class.create'then array['academicYearId','yearGroupId','name']when'subject.create'then array['name']
 when'person.configure'then array['displayName','role','status','effectiveFrom','effectiveTo','confirmAccessChange']when'enrollment.configure'then array['classId','studentId','status','effectiveFrom','effectiveTo','confirmAccessChange']when'assignment.configure'then array['classId','subjectId','teacherId','status','effectiveFrom','effectiveTo','confirmAccessChange']when'guardian.configure'then array['parentId','studentId','relationshipType','status','effectiveFrom','effectiveTo','confirmAccessChange']
 when'attendance.record'then array['classId','studentId','occurredOn','status','note','expectedRevision','correctionReason']when'timetable.create'then array['classId','subjectId','teacherId','dayOfWeek','startsAt','endsAt','effectiveFrom','effectiveTo','location']when'calendar.create'then array['classId','title','description','startsAt','endsAt','parentVisible']when'reportperiod.create'then array['termId','name','startsOn','endsOn','parentVisible']when'policy.approve'then array['expectedVersion','parentAttendanceVisible','parentUpcomingVisible','studentMessagingEnabled','recognitionEnabled','leaderboardEnabled','analyticsEnabled','reason','confirmPolicyApproval']else null end;
 if fields is null or payload is null or jsonb_typeof(payload)<>'object'or payload-fields<>'{}'::jsonb or octet_length(payload::text)>16384 then raise exception 'Invalid school command fields'using errcode='22023';end if;
 if command_name in('year.create','term.create','yeargroup.create','class.create','subject.create')and(length(btrim(payload->>'name'))not between 1 and 200 or payload->>'name'is null)then raise exception 'School name required'using errcode='22023';end if;
 if command_name='attendance.record'and((payload->>'expectedRevision')::integer is null or(payload->>'expectedRevision')::integer<0 or((payload->>'expectedRevision')::integer>0 and coalesce(length(btrim(payload->>'correctionReason')),0)=0))then raise exception 'Attendance revision and correction required'using errcode='22023';end if;
 if command_name='person.configure'and not(payload?&fields)then raise exception 'Complete member configuration required'using errcode='22023';end if;
end$$;
create function internal.school_command(command_name text,target_id uuid,payload jsonb,command_key text,fingerprint text,request_id text)returns jsonb language plpgsql security definer set search_path=''as $$
declare school uuid:="authorization".school_id();actor uuid:="authorization".actor_id();response jsonb;reservation jsonb;rid uuid;previous app.attendance_revisions;member app.memberships;parent app.memberships;student app.memberships;year app.academic_years;term app.terms;v_policy_version integer;role_name text;source uuid;
begin
 perform internal.validate_school_payload(command_name,payload);
 if command_name='attendance.record'then if not"authorization".can_record_attendance(school,(payload->>'classId')::uuid,(payload->>'studentId')::uuid)then raise exception 'Attendance scope denied'using errcode='42501';end if;else perform internal.require_school_admin();end if;
 -- Resolve target objects and current identity before stored response replay.
 if command_name='person.configure'then
  select*into member from app.memberships where school_id=school and actor_id=target_id;
  if not found or not exists(select 1 from auth.users u where u.id=target_id and u.deleted_at is null)then raise exception 'Provisioned current-school identity required'using errcode='42501';end if;
 elsif command_name in('enrollment.configure','assignment.configure','guardian.configure')then
  if (payload->>'confirmAccessChange')::boolean is distinct from true then raise exception 'Human access confirmation required'using errcode='22023';end if;
  source:=case when command_name='enrollment.configure'then(payload->>'studentId')::uuid when command_name='assignment.configure'then(payload->>'teacherId')::uuid else(payload->>'parentId')::uuid end;
  select*into member from app.memberships where school_id=school and actor_id=source;
  role_name:=case when command_name='enrollment.configure'then'student'when command_name='assignment.configure'then'teacher'else'parent'end;
  if not found or member.role<>role_name or member.status<>'active'or member.effective_from>now()or member.effective_to<=now()or not exists(select 1 from auth.users u where u.id=source and u.deleted_at is null)then raise exception 'Current provisioned role required'using errcode='42501';end if;
  if command_name='guardian.configure'then select*into student from app.memberships where school_id=school and actor_id=(payload->>'studentId')::uuid;if not found or student.role<>'student'or student.status<>'active'or student.effective_from>now()or student.effective_to<=now()or not exists(select 1 from auth.users u where u.id=student.actor_id and u.deleted_at is null)then raise exception 'Current learner required'using errcode='42501';end if;
  else if not exists(select 1 from app.classes where school_id=school and id=(payload->>'classId')::uuid and status='active')then raise exception 'Current class required'using errcode='42501';end if;end if;
  if command_name='assignment.configure'and not exists(select 1 from app.subjects where school_id=school and id=(payload->>'subjectId')::uuid)then raise exception 'Current subject required'using errcode='42501';end if;
 elsif command_name='term.create'then select*into year from app.academic_years where school_id=school and id=(payload->>'academicYearId')::uuid;if not found then raise exception 'Academic year denied'using errcode='42501';end if;
 elsif command_name='class.create'then if not exists(select 1 from app.academic_years where school_id=school and id=(payload->>'academicYearId')::uuid)or not exists(select 1 from app.year_groups where school_id=school and id=(payload->>'yearGroupId')::uuid)then raise exception 'Class scope denied'using errcode='42501';end if;
 elsif command_name='reportperiod.create'then select*into term from app.terms where school_id=school and id=(payload->>'termId')::uuid;if not found then raise exception 'Term denied'using errcode='42501';end if;
 elsif command_name='timetable.create'then if not exists(select 1 from app.teacher_assignments t join app.memberships m on m.school_id=t.school_id and m.actor_id=t.teacher_actor_id join app.classes c on c.school_id=t.school_id and c.id=t.class_id where t.school_id=school and t.class_id=(payload->>'classId')::uuid and t.subject_id=(payload->>'subjectId')::uuid and t.teacher_actor_id=(payload->>'teacherId')::uuid and t.status='active'and t.effective_from<=now()and(t.effective_to is null or t.effective_to>now())and m.role='teacher'and m.status='active'and m.effective_from<=now()and(m.effective_to is null or m.effective_to>now())and c.status='active')then raise exception 'Teacher timetable scope denied'using errcode='42501';end if;
 elsif command_name='calendar.create'and payload->>'classId'is not null then if not exists(select 1 from app.classes where school_id=school and id=(payload->>'classId')::uuid and status='active')then raise exception 'Calendar class denied'using errcode='42501';end if;
 end if;
 if command_name not in('details.update','year.create','term.create','yeargroup.create','class.create','subject.create','person.configure','enrollment.configure','assignment.configure','guardian.configure','attendance.record','timetable.create','calendar.create','reportperiod.create','policy.approve')then raise exception 'Unknown school command'using errcode='22023';end if;
 reservation:=internal.begin_command(command_key,'school.'||command_name,fingerprint);if reservation->>'state'='COMPLETED'then return reservation->'response';elsif reservation->>'state'<>'NEW'then raise exception 'School command in progress'using errcode='22023';end if;
 if command_name='details.update'then update app.schools set name=payload->>'name',country_code=payload->>'countryCode',languages=array(select jsonb_array_elements_text(payload->'languages'))where id=school returning id into rid;
 elsif command_name='year.create'then insert into app.academic_years(school_id,name,starts_on,ends_on)values(school,payload->>'name',(payload->>'startsOn')::date,(payload->>'endsOn')::date)returning id into rid;
 elsif command_name='term.create'then if(payload->>'startsOn')::date<year.starts_on or(payload->>'endsOn')::date>year.ends_on then raise exception 'Term outside year'using errcode='22023';end if;insert into app.terms(school_id,academic_year_id,name,starts_on,ends_on)values(school,year.id,payload->>'name',(payload->>'startsOn')::date,(payload->>'endsOn')::date)returning id into rid;
 elsif command_name='yeargroup.create'then insert into app.year_groups(school_id,name,ordinal)values(school,payload->>'name',(payload->>'ordinal')::integer)returning id into rid;
 elsif command_name='class.create'then insert into app.classes(school_id,academic_year_id,year_group_id,name)values(school,(payload->>'academicYearId')::uuid,(payload->>'yearGroupId')::uuid,payload->>'name')returning id into rid;
 elsif command_name='subject.create'then insert into app.subjects(school_id,name)values(school,payload->>'name')returning id into rid;
 elsif command_name='person.configure'then
  if(payload->>'confirmAccessChange')::boolean is distinct from true then raise exception 'Human access confirmation required'using errcode='22023';end if;
  perform pg_advisory_xact_lock(hashtextextended(school::text||':admin-memberships',0));
  if target_id=actor and(payload->>'role'<>'admin'or payload->>'status'<>'active'or(payload->>'effectiveFrom')::timestamptz>now()or(payload->>'effectiveTo')::timestamptz<=now())then raise exception 'Admin cannot remove own current access'using errcode='22023';end if;
  if member.role='admin'and(payload->>'role'<>'admin'or payload->>'status'<>'active')and not exists(select 1 from app.memberships m where m.school_id=school and m.actor_id<>target_id and m.role='admin'and m.status='active'and m.effective_from<=now()and(m.effective_to is null or m.effective_to>now()))then raise exception 'Last administrator protected'using errcode='22023';end if;
  update app.memberships set role=payload->>'role',status=payload->>'status',effective_from=(payload->>'effectiveFrom')::timestamptz,effective_to=(payload->>'effectiveTo')::timestamptz where school_id=school and actor_id=target_id;update app.people set display_name=payload->>'displayName'where school_id=school and actor_id=target_id;rid:=target_id;
 elsif command_name='enrollment.configure'then insert into app.enrollments(school_id,class_id,student_actor_id,status,effective_from,effective_to)values(school,(payload->>'classId')::uuid,(payload->>'studentId')::uuid,payload->>'status',(payload->>'effectiveFrom')::timestamptz,(payload->>'effectiveTo')::timestamptz)on conflict(school_id,class_id,student_actor_id)do update set status=excluded.status,effective_from=excluded.effective_from,effective_to=excluded.effective_to;rid:=(payload->>'studentId')::uuid;
 elsif command_name='assignment.configure'then insert into app.teacher_assignments(school_id,class_id,subject_id,teacher_actor_id,status,effective_from,effective_to)values(school,(payload->>'classId')::uuid,(payload->>'subjectId')::uuid,(payload->>'teacherId')::uuid,payload->>'status',(payload->>'effectiveFrom')::timestamptz,(payload->>'effectiveTo')::timestamptz)on conflict(school_id,class_id,subject_id,teacher_actor_id)do update set status=excluded.status,effective_from=excluded.effective_from,effective_to=excluded.effective_to;rid:=(payload->>'teacherId')::uuid;
 elsif command_name='guardian.configure'then insert into app.parent_relationships(school_id,parent_actor_id,student_actor_id,relationship_type,status,effective_from,effective_to)values(school,(payload->>'parentId')::uuid,(payload->>'studentId')::uuid,payload->>'relationshipType',payload->>'status',(payload->>'effectiveFrom')::timestamptz,(payload->>'effectiveTo')::timestamptz)on conflict(school_id,parent_actor_id,student_actor_id)do update set relationship_type=excluded.relationship_type,status=excluded.status,effective_from=excluded.effective_from,effective_to=excluded.effective_to;rid:=(payload->>'parentId')::uuid;
 elsif command_name='attendance.record'then
  perform pg_advisory_xact_lock(hashtextextended(school::text||':attendance:'||(payload->>'classId')||':'||(payload->>'studentId')||':'||(payload->>'occurredOn'),0));
  select*into previous from app.attendance_revisions ar where ar.school_id=school and ar.class_id=(payload->>'classId')::uuid and ar.learner_id=(payload->>'studentId')::uuid and ar.occurred_on=(payload->>'occurredOn')::date order by ar.revision desc limit 1;
  if coalesce(previous.revision,0)<>(payload->>'expectedRevision')::integer then raise exception 'Attendance revision mismatch'using errcode='22023';end if;
  insert into app.attendance_revisions(school_id,class_id,learner_id,occurred_on,revision,status,note,correction_reason,recorded_by,previous_id)values(school,(payload->>'classId')::uuid,(payload->>'studentId')::uuid,(payload->>'occurredOn')::date,coalesce(previous.revision,0)+1,payload->>'status',coalesce(payload->>'note',''),payload->>'correctionReason',actor,previous.id)returning id into rid;
 elsif command_name='timetable.create'then
  perform pg_advisory_xact_lock(hashtextextended(school::text||':timetable',0));
  if exists(select 1 from app.timetable_entries t where t.school_id=school and(t.class_id=(payload->>'classId')::uuid or t.teacher_id=(payload->>'teacherId')::uuid)and t.day_of_week=(payload->>'dayOfWeek')::integer and t.effective_from<=(payload->>'effectiveTo')::date and t.effective_to>=(payload->>'effectiveFrom')::date and t.starts_at<(payload->>'endsAt')::time and t.ends_at>(payload->>'startsAt')::time)then raise exception 'Timetable conflict'using errcode='22023';end if;
  insert into app.timetable_entries(school_id,class_id,subject_id,teacher_id,day_of_week,starts_at,ends_at,effective_from,effective_to,location,created_by)values(school,(payload->>'classId')::uuid,(payload->>'subjectId')::uuid,(payload->>'teacherId')::uuid,(payload->>'dayOfWeek')::integer,(payload->>'startsAt')::time,(payload->>'endsAt')::time,(payload->>'effectiveFrom')::date,(payload->>'effectiveTo')::date,coalesce(payload->>'location',''),actor)returning id into rid;
 elsif command_name='calendar.create'then insert into app.calendar_events(school_id,class_id,title,description,starts_at,ends_at,parent_visible,created_by)values(school,(payload->>'classId')::uuid,payload->>'title',coalesce(payload->>'description',''),(payload->>'startsAt')::timestamptz,(payload->>'endsAt')::timestamptz,(payload->>'parentVisible')::boolean,actor)returning id into rid;
 elsif command_name='reportperiod.create'then if(payload->>'startsOn')::date<term.starts_on or(payload->>'endsOn')::date>term.ends_on then raise exception 'Report period outside term'using errcode='22023';end if;insert into app.report_periods(school_id,term_id,name,starts_on,ends_on,parent_visible,created_by)values(school,term.id,payload->>'name',(payload->>'startsOn')::date,(payload->>'endsOn')::date,(payload->>'parentVisible')::boolean,actor)returning id into rid;
 elsif command_name='policy.approve'then
  if(payload->>'confirmPolicyApproval')::boolean is distinct from true or(payload->>'studentMessagingEnabled')::boolean is distinct from false then raise exception 'Conservative policy approval required'using errcode='22023';end if;
  perform pg_advisory_xact_lock(hashtextextended(school::text||':policy',0));select coalesce(max(p.version),0)into v_policy_version from app.school_policy_versions p where p.school_id=school;if v_policy_version<>(payload->>'expectedVersion')::integer then raise exception 'Policy version mismatch'using errcode='22023';end if;
  insert into app.school_policy_versions(school_id,version,parent_attendance_visible,parent_upcoming_visible,student_messaging_enabled,recognition_enabled,leaderboard_enabled,analytics_enabled,reason,approved_by)values(school,v_policy_version+1,(payload->>'parentAttendanceVisible')::boolean,(payload->>'parentUpcomingVisible')::boolean,false,(payload->>'recognitionEnabled')::boolean,(payload->>'leaderboardEnabled')::boolean,(payload->>'analyticsEnabled')::boolean,payload->>'reason',actor)returning id into rid;
 end if;
 response:=jsonb_build_object('id',rid,'command',command_name,'schoolId',school);
 if command_name='attendance.record'then select jsonb_build_object('id',id,'classId',class_id,'learnerId',learner_id,'occurredOn',occurred_on,'revision',revision,'status',status,'note',note,'correctionReason',correction_reason,'recordedAt',recorded_at)into response from app.attendance_revisions where school_id=school and id=rid;end if;
 if command_name='policy.approve'then response:=response||jsonb_build_object('version',v_policy_version+1);end if;
 perform internal.append_audit('school.'||command_name,'school_operation',rid,request_id,'succeeded',jsonb_build_object('command',command_name));
 perform internal.enqueue_event('school.updated','school_operation',rid,1,jsonb_build_object('command',command_name),'school:'||md5(actor::text||':'||command_name||':'||command_key));
 perform internal.finish_command(command_key,'school.'||command_name,fingerprint,response);return response;
end$$;
create function "authorization".can_read_school_schedule(target_school uuid,target_class uuid)returns boolean language sql stable security definer set search_path=''as $$select coalesce("authorization".school_operations_access(target_school)and(target_class is null or"authorization".can_view_class(target_school,target_class))and("authorization".current_role(target_school)<>'parent'or exists(select 1 from app.school_policy_versions p where p.school_id=target_school and p.version=(select max(version)from app.school_policy_versions where school_id=target_school)and p.parent_upcoming_visible)and exists(select 1 from app.parent_relationships r where r.school_id=target_school and r.parent_actor_id="authorization".actor_id()and"authorization".can_view_person(target_school,r.student_actor_id))),false)$$;
create function "authorization".can_read_attendance(target_school uuid,target_class uuid,target_learner uuid)returns boolean language sql stable security definer set search_path=''as $$select coalesce("authorization".school_operations_access(target_school)and"authorization".can_view_person(target_school,target_learner)and"authorization".can_view_class(target_school,target_class)and("authorization".current_role(target_school)<>'parent'or exists(select 1 from app.school_policy_versions p where p.school_id=target_school and p.version=(select max(version)from app.school_policy_versions where school_id=target_school)and p.parent_attendance_visible)),false)$$;
create function internal.school_list(resource text,filters jsonb)returns jsonb language plpgsql security definer set search_path=''as $$
declare school uuid:="authorization".school_id();role_name text:="authorization".current_role("authorization".school_id());statement text;items jsonb;all_rows jsonb;lim integer;cursor_id uuid;learner uuid;class_filter uuid;
begin
 if not"authorization".school_operations_access(school)then raise exception 'School operations denied'using errcode='42501';end if;
 lim:=(filters->>'limit')::integer;cursor_id:=(filters->>'cursor')::uuid;learner:=(filters->>'learnerId')::uuid;class_filter:=(filters->>'classId')::uuid;
 if lim is null or lim not between 1 and 100 then raise exception 'Bounded school list required'using errcode='22023';end if;
 if resource in('people','enrollments','teacher-assignments','guardian-relationships','policies','entitlements')and role_name not in('admin','coordinator')then raise exception 'School administration list denied'using errcode='42501';end if;
 if resource in('years','terms','year-groups','classes','subjects','report-periods')and role_name not in('admin','coordinator','teacher')then raise exception 'School staff list denied'using errcode='42501';end if;
 if learner is not null and not"authorization".can_view_person(school,learner)then raise exception 'Learner filter denied'using errcode='42501';end if;
 if class_filter is not null and not"authorization".can_view_class(school,class_filter)then raise exception 'Class filter denied'using errcode='42501';end if;
 case resource
 when 'years'then statement:='select id,jsonb_build_object(''id'',id,''name'',name,''startsOn'',starts_on,''endsOn'',ends_on)row from app.academic_years where school_id=$1';
 when 'terms'then statement:='select id,jsonb_build_object(''id'',id,''academicYearId'',academic_year_id,''name'',name,''startsOn'',starts_on,''endsOn'',ends_on)row from app.terms where school_id=$1';
 when 'year-groups'then statement:='select id,jsonb_build_object(''id'',id,''name'',name,''ordinal'',ordinal)row from app.year_groups where school_id=$1';
 when 'classes'then statement:='select id,jsonb_build_object(''id'',id,''name'',name,''academicYearId'',academic_year_id,''yearGroupId'',year_group_id,''status'',status)row from app.classes where school_id=$1 and "authorization".can_view_class(school_id,id)';
 when 'subjects'then statement:='select id,jsonb_build_object(''id'',id,''name'',name)row from app.subjects where school_id=$1';
 when 'people'then statement:='select m.actor_id id,jsonb_build_object(''id'',m.actor_id,''displayName'',p.display_name,''role'',m.role,''status'',m.status,''effectiveFrom'',m.effective_from,''effectiveTo'',m.effective_to,''synthetic'',p.synthetic)row from app.memberships m join app.people p on p.school_id=m.school_id and p.actor_id=m.actor_id where m.school_id=$1';
 when 'enrollments'then statement:='select md5(class_id::text||student_actor_id::text)::uuid id,jsonb_build_object(''id'',md5(class_id::text||student_actor_id::text)::uuid,''classId'',class_id,''studentId'',student_actor_id,''status'',status,''effectiveFrom'',effective_from,''effectiveTo'',effective_to)row from app.enrollments where school_id=$1 and($3::uuid is null or student_actor_id=$3)and($4::uuid is null or class_id=$4)';
 when 'teacher-assignments'then statement:='select md5(class_id::text||subject_id::text||teacher_actor_id::text)::uuid id,jsonb_build_object(''id'',md5(class_id::text||subject_id::text||teacher_actor_id::text)::uuid,''classId'',class_id,''subjectId'',subject_id,''teacherId'',teacher_actor_id,''status'',status,''effectiveFrom'',effective_from,''effectiveTo'',effective_to)row from app.teacher_assignments where school_id=$1 and($4::uuid is null or class_id=$4)';
 when 'guardian-relationships'then statement:='select md5(parent_actor_id::text||student_actor_id::text)::uuid id,jsonb_build_object(''id'',md5(parent_actor_id::text||student_actor_id::text)::uuid,''parentId'',parent_actor_id,''studentId'',student_actor_id,''relationshipType'',relationship_type,''status'',status,''effectiveFrom'',effective_from,''effectiveTo'',effective_to)row from app.parent_relationships where school_id=$1 and($3::uuid is null or student_actor_id=$3)';
 when 'attendance'then statement:='select id,jsonb_build_object(''id'',id,''classId'',class_id,''learnerId'',learner_id,''occurredOn'',occurred_on,''revision'',revision,''status'',status,''note'',case when "authorization".current_role(school_id)in(''admin'',''teacher'',''coordinator'')then note else null end,''recordedAt'',recorded_at)row from(select distinct on(class_id,learner_id,occurred_on)*from app.attendance_revisions where school_id=$1 and($3::uuid is null or learner_id=$3)and($4::uuid is null or class_id=$4)order by class_id,learner_id,occurred_on,revision desc)latest where "authorization".can_read_attendance(school_id,class_id,learner_id)';
 when 'timetable'then statement:='select id,jsonb_build_object(''id'',id,''classId'',class_id,''subjectId'',subject_id,''teacherId'',teacher_id,''dayOfWeek'',day_of_week,''startsAt'',to_char(starts_at,''HH24:MI''),''endsAt'',to_char(ends_at,''HH24:MI''),''effectiveFrom'',effective_from,''effectiveTo'',effective_to,''location'',location)row from app.timetable_entries where school_id=$1 and($4::uuid is null or class_id=$4)and "authorization".can_read_school_schedule(school_id,class_id)';
 when 'calendar'then statement:='select id,jsonb_build_object(''id'',id,''classId'',class_id,''title'',title,''description'',description,''startsAt'',starts_at,''endsAt'',ends_at,''parentVisible'',parent_visible)row from app.calendar_events where school_id=$1 and($4::uuid is null or class_id=$4)and "authorization".can_read_school_schedule(school_id,class_id)and("authorization".current_role(school_id)<>''parent''or parent_visible)';
 when 'report-periods'then statement:='select id,jsonb_build_object(''id'',id,''termId'',term_id,''name'',name,''startsOn'',starts_on,''endsOn'',ends_on,''parentVisible'',parent_visible)row from app.report_periods where school_id=$1';
 when 'policies'then statement:='select id,jsonb_build_object(''id'',id,''version'',version,''parentAttendanceVisible'',parent_attendance_visible,''parentUpcomingVisible'',parent_upcoming_visible,''studentMessagingEnabled'',student_messaging_enabled,''recognitionEnabled'',recognition_enabled,''leaderboardEnabled'',leaderboard_enabled,''analyticsEnabled'',analytics_enabled,''reason'',reason,''approvedBy'',approved_by,''approvedAt'',approved_at)row from app.school_policy_versions where school_id=$1';
 when 'entitlements'then statement:='select md5(code)::uuid id,jsonb_build_object(''id'',md5(code)::uuid,''code'',code,''enabled'',enabled,''effectiveFrom'',effective_from,''effectiveTo'',effective_to)row from app.entitlements where school_id=$1';
 else raise exception 'Unknown school resource'using errcode='22023';end case;
 execute 'select coalesce(jsonb_agg(row order by id),''[]''::jsonb)from(select id,row from('||statement||')owned where($2::uuid is null or id>$2)order by id limit $5)bounded'into all_rows using school,cursor_id,learner,class_filter,lim+1;
 if octet_length(all_rows::text)>500000 then raise exception 'School view requires bounded review'using errcode='22023';end if;
 select coalesce(jsonb_agg(value order by ordinal),'[]'::jsonb)into items from jsonb_array_elements(all_rows)with ordinality entries(value,ordinal)where ordinal<=lim;
 return jsonb_build_object('items',items,'nextCursor',case when jsonb_array_length(all_rows)>lim then items->(lim-1)->>'id'else null end);
end$$;
create function internal.school_context()returns jsonb language plpgsql security definer set search_path=''as $$
declare school uuid:="authorization".school_id();policy app.school_policy_versions;context jsonb;
begin
 if not"authorization".school_operations_access(school)then raise exception 'School context denied'using errcode='42501';end if;
 select*into policy from app.school_policy_versions where school_id=school order by version desc limit 1;
 select jsonb_build_object('school',jsonb_build_object('id',id,'name',name,'countryCode',country_code,'languages',languages),'policy',jsonb_build_object('version',coalesce(policy.version,0),'parentAttendanceVisible',coalesce(policy.parent_attendance_visible,false),'parentUpcomingVisible',coalesce(policy.parent_upcoming_visible,false),'studentMessagingEnabled',false,'recognitionEnabled',coalesce(policy.recognition_enabled,false),'leaderboardEnabled',coalesce(policy.leaderboard_enabled,false),'analyticsEnabled',coalesce(policy.analytics_enabled,false)),
 'intelligence',jsonb_build_object('fixtureSchoolApproved',exists(select 1 from app.intelligence_policies p where p.school_id=school and p.fixture_enabled),'liveSchoolApproved',exists(select 1 from app.intelligence_policies p where p.school_id=school and p.live_enabled),'availability','SERVER_CONFIG_AND_APPROVED_POLICY_REQUIRED'))into context from app.schools where id=school;
 return context||jsonb_build_object('attendance',internal.school_list('attendance','{"limit":25}'),'timetable',internal.school_list('timetable','{"limit":25}'),'calendar',internal.school_list('calendar','{"limit":25}'));
end$$;
do $$declare tab text;begin foreach tab in array array['school_policy_versions','attendance_revisions','timetable_entries','calendar_events','report_periods']loop execute format('alter table app.%I enable row level security',tab);execute format('alter table app.%I force row level security',tab);execute format('create trigger immutable_history before update or delete on app.%I for each row execute function internal.academic_history_immutable()',tab);execute format('create trigger immutable_truncate before truncate on app.%I for each statement execute function internal.academic_history_immutable()',tab);end loop;end$$;
create policy school_policies_read on app.school_policy_versions for select to cuevo_api using("authorization".school_operations_access(school_id)and"authorization".current_role(school_id)in('admin','coordinator'));
create policy school_attendance_read on app.attendance_revisions for select to cuevo_api using("authorization".can_read_attendance(school_id,class_id,learner_id));
create policy school_timetable_read on app.timetable_entries for select to cuevo_api using("authorization".can_read_school_schedule(school_id,class_id));
create policy school_calendar_read on app.calendar_events for select to cuevo_api using("authorization".can_read_school_schedule(school_id,class_id)and("authorization".current_role(school_id)<>'parent'or parent_visible));
create policy report_periods_read on app.report_periods for select to cuevo_api using("authorization".school_operations_access(school_id)and"authorization".current_role(school_id)in('admin','coordinator','teacher'));
revoke all on app.school_policy_versions,app.attendance_revisions,app.timetable_entries,app.calendar_events,app.report_periods from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant select on app.school_policy_versions,app.attendance_revisions,app.timetable_entries,app.calendar_events,app.report_periods to cuevo_api;
revoke execute on function "authorization".school_operations_access(uuid),"authorization".can_record_attendance(uuid,uuid,uuid),"authorization".can_read_attendance(uuid,uuid,uuid),"authorization".can_read_school_schedule(uuid,uuid),internal.require_school_admin(),internal.validate_school_payload(text,jsonb),internal.school_command(text,uuid,jsonb,text,text,text),internal.school_list(text,jsonb),internal.school_context()from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant execute on function "authorization".school_operations_access(uuid),"authorization".can_record_attendance(uuid,uuid,uuid),"authorization".can_read_attendance(uuid,uuid,uuid),"authorization".can_read_school_schedule(uuid,uuid),internal.school_command(text,uuid,jsonb,text,text,text),internal.school_list(text,jsonb),internal.school_context()to cuevo_api;
commit;
